/* selectRprsTelno - kim.seong.ok */

SELECT 
    RPRS_TELNO
FROM SAA000
WHERE 1=1
AND INST_NO = #{INST_NO}

/* selectDailyRsvtPreconList - kim.seong.ok */
SELECT B.RESRCE_CL_MNG_ESNTAL_NO , B.RSVT_SN , B.INST_NO , B.UNT_TASKWK_SE_CD /* , B.USER_ID */ , B.RESRCE_CL_MNG_LCLAS_SE_CD , B.RSVT_SE_CD , B.RESRCE_NM , B.RSVT_BGNG_YMD , B.RSVT_END_YMD , B.RSVT_BGNG_HR , B.RSVT_END_HR , B.RSVT_APLY_ENFSN_NO , B.USE_PURPS_SE_CD , B.USE_PURPS_CN , B.RM_CN , B.RSVT_APLY_YMD , B.RSVT_STTS_SE_CD , B.RSVT_CHRCTR_SNDNG_YMD , B.RSVT_CHRCTR_SNDNG_HR , B.RSVT_CHRCTR_SNDNG_CN , B.RSVT_CHRCTR_SNDNG_YN , B.FRST_RGTR_ID , B.FRST_REG_DT , B.LAST_MDFR_ID , B.LAST_MDFCN_DT
, TO_CHAR(TO_date(RSVT_BGNG_YMD, 'YYYYMMDD'), 'dy') AS START_DAYOFWEEK , TO_CHAR(TO_date(RSVT_END_YMD, 'YYYYMMDD'), 'dy') AS END_DAYOFWEEK , C##RG.DEC_B64(C##RG.SA_FN_GET_NAME(B.USER_ID)) AS RSVCTM , A.USER_ID FROM SBD300 A JOIN SBD310 B ON A.INST_NO = B.INST_NO AND A.RESRCE_CL_MNG_ESNTAL_NO = B.RESRCE_CL_MNG_ESNTAL_NO AND A.UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD
WHERE A.INST_NO = #{INST_NO} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND B.RSVT_STTS_SE_CD = '01' AND TO_NUMBER(#{SEARCH_DATE}) <= TO_NUMBER(B.RSVT_END_YMD) AND TO_NUMBER(B.RSVT_BGNG_YMD) <= TO_NUMBER(#{SEARCH_DATE})
AND B.RESRCE_CL_MNG_LCLAS_SE_CD = #{RESRCE_CL_MNG_LCLAS_SE_CD}

/* selectWeeklyRsvtPreconList - kim.seong.ok */
SELECT
B.RESRCE_CL_MNG_ESNTAL_NO , B.RSVT_SN , B.INST_NO , B.UNT_TASKWK_SE_CD /* , B.USER_ID */ , B.RESRCE_CL_MNG_LCLAS_SE_CD , B.RSVT_SE_CD , B.RESRCE_NM , B.RSVT_BGNG_YMD , B.RSVT_END_YMD , B.RSVT_BGNG_HR , B.RSVT_END_HR , B.RSVT_APLY_ENFSN_NO , B.USE_PURPS_SE_CD , B.USE_PURPS_CN , B.RM_CN , B.RSVT_APLY_YMD , B.RSVT_STTS_SE_CD , B.RSVT_CHRCTR_SNDNG_YMD , B.RSVT_CHRCTR_SNDNG_HR , B.RSVT_CHRCTR_SNDNG_CN , B.RSVT_CHRCTR_SNDNG_YN , B.FRST_RGTR_ID , B.FRST_REG_DT , B.LAST_MDFR_ID , B.LAST_MDFCN_DT
, TO_CHAR(TO_date(RSVT_BGNG_YMD, 'YYYYMMDD'), 'dy') AS START_DAYOFWEEK , TO_CHAR(TO_date(RSVT_END_YMD, 'YYYYMMDD'), 'dy') AS END_DAYOFWEEK , C##RG.DEC_B64(C##RG.SA_FN_GET_NAME(B.USER_ID)) AS RSVCTM , A.USER_ID FROM SBD300 A JOIN SBD310 B ON A.INST_NO = B.INST_NO AND A.RESRCE_CL_MNG_ESNTAL_NO = B.RESRCE_CL_MNG_ESNTAL_NO AND A.UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD
WHERE A.INST_NO = #{INST_NO} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND B.RSVT_STTS_SE_CD = '01' AND TO_NUMBER(#{WEEKLY_START_DATE}) <= TO_NUMBER(B.RSVT_END_YMD) AND TO_NUMBER(B.RSVT_BGNG_YMD) <= TO_NUMBER(#{WEEKLY_END_DATE})
AND B.RESRCE_CL_MNG_LCLAS_SE_CD = #{RESRCE_CL_MNG_LCLAS_SE_CD}

/* selectRsvtPreconList - kim.seong.ok */
SELECT
B.RESRCE_CL_MNG_ESNTAL_NO , B.RSVT_SN , B.INST_NO , B.UNT_TASKWK_SE_CD , B.USER_ID , B.RESRCE_CL_MNG_LCLAS_SE_CD , B.RSVT_SE_CD , B.RESRCE_NM , B.RSVT_BGNG_YMD , B.RSVT_END_YMD , B.RSVT_BGNG_HR , B.RSVT_END_HR , B.RSVT_APLY_ENFSN_NO , B.USE_PURPS_SE_CD , B.USE_PURPS_CN , B.RM_CN , B.RSVT_APLY_YMD , B.RSVT_STTS_SE_CD , B.RSVT_CHRCTR_SNDNG_YMD , B.RSVT_CHRCTR_SNDNG_HR , B.RSVT_CHRCTR_SNDNG_CN , B.RSVT_CHRCTR_SNDNG_YN , B.FRST_RGTR_ID , B.FRST_REG_DT , B.LAST_MDFR_ID , B.LAST_MDFCN_DT
, TO_CHAR(TO_date(RSVT_BGNG_YMD, 'YYYYMMDD'), 'dy') AS START_DAYOFWEEK , TO_CHAR(TO_date(RSVT_END_YMD, 'YYYYMMDD'), 'dy') AS END_DAYOFWEEK , C##RG.DEC_B64(C##RG.SA_FN_GET_NAME(B.USER_ID)) AS RSVCTM FROM SBD300 A JOIN SBD310 B ON A.INST_NO = B.INST_NO AND A.RESRCE_CL_MNG_ESNTAL_NO = B.RESRCE_CL_MNG_ESNTAL_NO AND A.UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD
WHERE A.INST_NO = #{INST_NO} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND B.RSVT_STTS_SE_CD = '01' AND TO_NUMBER(#{SEARCH_DATE}) <= TO_NUMBER(B.RSVT_END_YMD) AND TO_NUMBER(B.RSVT_BGNG_YMD) <= TO_NUMBER(#{SEARCH_DATE})
AND B.RESRCE_CL_MNG_LCLAS_SE_CD = #{RESRCE_CL_MNG_LCLAS_SE_CD}

