/* updateResrceClMngDtl - kim.seong.ok */


UPDATE SBD300 SET

    RESRCE_CL_MNG_LCLAS_SE_CD   = #{RESRCE_CL_MNG_LCLAS_SE_CD},     /* 자원분류관리대분류구분코드           */
    RESRCE_NM                   = #{RESRCE_NM},                     /* 자원명        */
    USE_YN                      = #{USE_YN},                        /* 사용여부       */
    SCHDL_RSVT_CONECA_USE_YN       = #{SCHDL_RSVT_CONECA_USE_YN},         /* 일정예약연결사용여부       */
    LAST_MDFR_ID                = #{LAST_MDFR_ID},                  /* 최종수정자아이디        */
    LAST_MDFCN_DT               = SYSDATE                           /* 최종수정일시           */

WHERE INST_NO = #{INST_NO}
AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND USER_ID = #{USER_ID}
AND RESRCE_CL_MNG_ESNTAL_NO = #{RESRCE_CL_MNG_ESNTAL_NO}
AND DEL_YN = 'N'

/* deleteResrceClMngDtl - kim.seong.ok */


UPDATE SBD300 SET

    DEL_YN = 'Y',
    LAST_MDFR_ID               = #{LAST_MDFR_ID},                       /* 최종수정자아이디        */
    LAST_MDFCN_DT              = SYSDATE                                /* 최종수정일시           */

WHERE INST_NO = #{INST_NO}
AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND USER_ID = #{USER_ID}
AND RESRCE_CL_MNG_ESNTAL_NO = #{RESRCE_CL_MNG_ESNTAL_NO}

