SELECT NVL(MAX(RSVT_SN)+1 ,1) FROM SBD310
/* insertResrceRsvtDtl - kim.seong.ok */
INSERT INTO SBD310 ( RESRCE_CL_MNG_ESNTAL_NO /* 자원분류관리고유번호 */ ,RSVT_SN /* 예약일련번호 */ ,INST_NO /* 기관번호 */ ,UNT_TASKWK_SE_CD /* 단위업무구분코드 */ ,USER_ID /* 사용자아이디 */ ,RESRCE_CL_MNG_LCLAS_SE_CD /* 자원분류관리대분류구분코드 */ ,RSVT_SE_CD /* 예약구분코드 */ ,RESRCE_NM /* 자원명 */ ,RSVT_BGNG_YMD /* 예약시작일자 */ ,RSVT_END_YMD /* 예약종료일자 */ ,RSVT_BGNG_HR /* 예약시작시간 */ ,RSVT_END_HR /* 예약종료시간 */ ,RSVT_APLY_ENFSN_NO /* 예약신청자번호 */ ,USE_PURPS_CN /* 사용목적내용 */ ,RM_CN /* 비고내용 */ ,RSVT_APLY_YMD /* 예약신청일자 */ ,RSVT_STTS_SE_CD /* 예약상태구분코드 */ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,FRST_REG_DT /* 최초등록일시 */ ,LAST_MDFR_ID /* 최종수정자아이디 */ ,LAST_MDFCN_DT /* 최종수정일시 */ ) VALUES ( #{RESRCE_CL_MNG_ESNTAL_NO}, /* 자원분류관리고유번호 */ #{RSVT_SN}, /* 예약일련번호 */ #{INST_NO}, /* 기관번호 */ #{UNT_TASKWK_SE_CD}, /* 단위업무구분코드 */ #{USER_ID}, /* 사용자아이디 */ #{RESRCE_CL_MNG_LCLAS_SE_CD}, /* 자원분류관리대분류구분코드 */ '01', /* 예약구분코드(자원예약) */ #{RESRCE_NM}, /* 자원명 */ #{RSVT_BGNG_YMD}, /* 예약시작일자 */ #{RSVT_END_YMD}, /* 예약종료일자 */ #{RSVT_BGNG_HR}, /* 예약시작시간 */ #{RSVT_END_HR}, /* 예약종료시간 */ #{RSVT_APLY_ENFSN_NO}, /* 예약신청자번호 */ #{USE_PURPS_CN}, /* 사용목적내용 */ #{RM_CN}, /* 비고내용 */ #{RSVT_APLY_YMD}, /* 예약신청일자 */ '01', /* 예약상태구분코드 */ #{USER_ID}, /* 최초등록자아이디 */ SYSDATE, /* 최초등록일시 */ #{USER_ID}, /* 최종수정자아이디 */ SYSDATE /* 최종수정일시 */ )

mapper.update:
/* updateResrceRsvtDtl - kim.seong.ok */


UPDATE SBD310 SET

    RSVT_BGNG_YMD               = #{RSVT_BGNG_YMD},                     /* 예약시작일자           */
    RSVT_END_YMD                = #{RSVT_END_YMD},                      /* 예약종료일자        */
    RSVT_BGNG_HR                = #{RSVT_BGNG_HR},                      /* 예약시작시간           */
    RSVT_END_HR                 = #{RSVT_END_HR},                       /* 예약종료시간        */
    USE_PURPS_CN                = #{USE_PURPS_CN},                      /* 사용목적내용       */
    RM_CN                       = #{RM_CN},                             /* 비고내용       */
    RSVT_APLY_YMD               = #{RSVT_APLY_YMD},                     /* 예약신청일        */
    RSVT_STTS_SE_CD             = '01',                                 /* 예약상태구분코드        */
    LAST_MDFR_ID                = #{LAST_MDFR_ID},                      /* 최종수정자아이디        */
    LAST_MDFCN_DT               = SYSDATE                               /* 최종수정일시           */

WHERE INST_NO = #{INST_NO}
AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND USER_ID = #{USER_ID}
AND RESRCE_CL_MNG_ESNTAL_NO = #{RESRCE_CL_MNG_ESNTAL_NO}
AND RESRCE_CL_MNG_LCLAS_SE_CD = #{RESRCE_CL_MNG_LCLAS_SE_CD}
AND RSVT_SN = #{RSVT_SN} 
AND RSVT_SE_CD = '01'

/* deleteResrceRsvtDtl - kim.seong.ok */


UPDATE SBD310 SET

    RSVT_STTS_SE_CD             = '02',                                 /* 예약상태구분코드        */
    LAST_MDFR_ID                = #{LAST_MDFR_ID},                      /* 최종수정자아이디        */
    LAST_MDFCN_DT               = SYSDATE                               /* 최종수정일시           */

WHERE INST_NO = #{INST_NO}
AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND USER_ID = #{USER_ID}
AND RESRCE_CL_MNG_ESNTAL_NO = #{RESRCE_CL_MNG_ESNTAL_NO}
AND RESRCE_CL_MNG_LCLAS_SE_CD = #{RESRCE_CL_MNG_LCLAS_SE_CD}
AND RSVT_SN = #{RSVT_SN} 
AND RSVT_SE_CD = '01'

