/* insertSchdlRsvtDtl - kim.seong.ok */
INSERT INTO SBD310 ( RESRCE_CL_MNG_ESNTAL_NO /* 자원분류관리고유번호 */ ,RSVT_SN /* 예약일련번호 */ ,INST_NO /* 기관번호 */ ,UNT_TASKWK_SE_CD /* 단위업무구분코드 */ ,USER_ID /* 사용자아이디 */ ,RESRCE_CL_MNG_LCLAS_SE_CD /* 자원분류관리대분류구분코드 */ ,RSVT_SE_CD /* 예약구분코드 */ ,RESRCE_NM /* 자원명 */ ,RSVT_BGNG_YMD /* 예약시작일자 */ ,RSVT_END_YMD /* 예약종료일자 */ ,RSVT_BGNG_HR /* 예약시작시간 */ ,RSVT_END_HR /* 예약종료시간 */ ,RSVT_APLY_ENFSN_NO /* 예약신청자번호 */ ,USE_PURPS_SE_CD /* 사용목적구분코드 */ ,RM_CN /* 비고내용 */ ,RSVT_APLY_YMD /* 예약신청일자 */ ,RSVT_STTS_SE_CD /* 예약상태구분코드 */ ,RSVT_CHRCTR_SNDNG_YMD /* 예약문자발송일 */ ,RSVT_CHRCTR_SNDNG_HR /* 예약문자발송시간 */ ,RSVT_CHRCTR_SNDNG_CN /* 예약문자발송내용 */ ,RSVT_CHRCTR_SNDNG_YN /* 예약문자발송여부 */ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,FRST_REG_DT /* 최초등록일시 */ ,LAST_MDFR_ID /* 최종수정자아이디 */ ,LAST_MDFCN_DT /* 최종수정일시 */ ) VALUES ( #{RESRCE_CL_MNG_ESNTAL_NO}, /* 자원분류관리고유번호 */ #{RSVT_SN}, /* 예약일련번호 */ #{INST_NO}, /* 기관번호 */ #{UNT_TASKWK_SE_CD}, /* 단위업무구분코드 */ #{USER_ID}, /* 사용자아이디 */ #{RESRCE_CL_MNG_LCLAS_SE_CD}, /* 자원분류관리대분류구분코드 */ '02', /* 예약구분코드(일정예약) */ #{RESRCE_NM}, /* 자원명 */ #{RSVT_BGNG_YMD}, /* 예약시작일자 */ #{RSVT_END_YMD}, /* 예약종료일자 */ #{RSVT_BGNG_HR}, /* 예약시작시간 */ #{RSVT_END_HR}, /* 예약종료시간 */ #{RSVT_APLY_ENFSN_NO}, /* 예약신청자번호 */ #{USE_PURPS_SE_CD}, /* 사용목적구분코드 */ #{RM_CN}, /* 비고내용 */ #{RSVT_APLY_YMD}, /* 예약신청일자 */ '01', /* 예약상태구분코드 */ #{RSVT_CHRCTR_SNDNG_YMD}, /* 예약문자발송일 */ #{RSVT_CHRCTR_SNDNG_HR}, /* 예약문자발송시간 */ #{RSVT_CHRCTR_SNDNG_CN}, /* 예약문자발송내용 */ #{RSVT_CHRCTR_SNDNG_YN}, /* 예약문자발송여부 */ #{FRST_RGTR_ID}, /* 최초등록자아이디 */ SYSDATE, /* 최초등록일시 */ #{LAST_MDFR_ID}, /* 최종수정자아이디 */ SYSDATE /* 최종수정일시 */ )



        SELECT ISRY_SMS.MMS_CONTENTS_INFO_SEQ.NEXTVAL AS CONT_SEQ FROM DUAL


/* insertMmsContentsInfo (MMS 컨텐츠정보 INSERT) - Lee Hye Sun */
INSERT INTO ISRY_SMS.MMS_CONTENTS_INFO (
      CONT_SEQ                             --MMS컨텐츠
    , FILE_CNT                             --MMS 전송시 첨부파일 갯수 
    , MMS_BODY                             --본문내용
    , MMS_SUBJECT                          --메시지타이틀
) VALUES (
      #{CONT_SEQ}
    , NVL(#{FILE_CNT}, 0)
    , #{RSVT_CHRCTR_CN}
    , SUBSTR(#{RSVT_CHRCTR_CN}, 0, 8) || '..'
)

