INSERT INTO SBD320 ( RESRCE_CL_MNG_ESNTAL_NO /* 자원분류관리고유번호 */ ,RSVT_SN /* 예약일련번호 */ ,INDEX_SN /* 색인일련번호 */ ,TRPR_INFO_NO /* 대상자정보번호 */ ,CASE_MNG_NO /* 사례관리번호 */ ,CASE_MNG_ODRNO /* 사례관리차수 */ ,MSSAGE_ESNTAL_NO /* 메세지고유번호 */ ,MMS_CNTT_NO /* MMS컨텐츠번호 */ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,FRST_REG_DT /* 최초등록일시 */ ,LAST_MDFR_ID /* 최종수정자아이디 */ ,LAST_MDFCN_DT /* 최종수정일시 */ ) VALUES ( #{RESRCE_CL_MNG_ESNTAL_NO}, /* 자원분류관리고유번호 */ #{RSVT_SN}, /* 예약일련번호 */ #{INDEX_SN}, /* 색인일련번호 */ #{TRPR_INFO_NO}, /* 대상자정보번호 */ #{CASE_MNG_NO}, /* 사례관리번호 */ #{CASE_MNG_ODRNO}, /* 사례관리차수 */ #{MSG_SEQ}, /* 메세지고유번호 */ #{CONT_SEQ}, /* MMS컨텐츠번호 */ #{FRST_RGTR_ID}, /* 최초등록자아이디 */ SYSDATE, /* 최초등록일시 */ #{LAST_MDFR_ID}, /* 최종수정자아이디 */ SYSDATE /* 최종수정일시 */ )

SELECT NVL(MAX(INDEX_SN)+1 ,1) FROM SBD330
/* insertSchdlRsvtPic - kim.seong.ok */
INSERT INTO SBD330 ( RESRCE_CL_MNG_ESNTAL_NO /* 자원분류관리고유번호 */ ,RSVT_SN /* 예약일련번호 */ ,INDEX_SN /* 색인일련번호 */ ,PIC_ID /* 담당자아이디 */ ,PIC_ENFSN_NO /* 담당자종사자번호 */ ,PCHPRS_YN /* 주담당자여부 */ ,MSSAGE_ESNTAL_NO /* 메세지고유번호 */ ,MMS_CNTT_NO /* MMS컨텐츠번호 */ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,FRST_REG_DT /* 최초등록일시 */ ,LAST_MDFR_ID /* 최종수정자아이디 */ ,LAST_MDFCN_DT /* 최종수정일시 */ ) VALUES ( #{RESRCE_CL_MNG_ESNTAL_NO}, /* 자원분류관리고유번호 */ #{RSVT_SN}, /* 예약일련번호 */ #{INDEX_SN}, /* 색인일련번호 */ #{PIC_USER_ID}, /* 담당자아이디 */ #{PIC_NO}, /* 담당자종사자번호 */ #{PCHPRS_YN}, /* 주담당자여부 */ #{MSG_SEQ}, /* 메세지고유번호 */ #{CONT_SEQ}, /* MMS컨텐츠번호 */ #{FRST_RGTR_ID}, /* 최초등록자아이디 */ SYSDATE, /* 최초등록일시 */ #{LAST_MDFR_ID}, /* 최종수정자아이디 */ SYSDATE /* 최종수정일시 */ )

mapper.select:
/* selectSchdlRsvtPicDtl - kim.seong.ok */
SELECT B.RESRCE_CL_MNG_ESNTAL_NO /* 자원분류관리고유번호 */ ,B.RSVT_SN /* 예약일렬번호(색인일련번호) */ ,B.INDEX_SN /* 색인일렬번호 */ , B.PIC_ID /* 담당자 아이디 */ ,C##RG.DEC_B64(C##RG.SA_FN_GET_NAME(B.PIC_ID)) AS PIC_NM /* 담당자 */ ,B.PCHPRS_YN /* 주담당자여부 */ ,B.PIC_ENFSN_NO AS PIC_NO FROM SBD310 A , SBD330 B WHERE 1=1 AND A.RESRCE_CL_MNG_ESNTAL_NO = B.RESRCE_CL_MNG_ESNTAL_NO AND A.RSVT_SN = B.RSVT_SN AND A.INST_NO = #{INST_NO} AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND A.RESRCE_CL_MNG_ESNTAL_NO = #{RESRCE_CL_MNG_ESNTAL_NO} AND A.RSVT_SN = #{RSVT_SN}
ORDER BY PCHPRS_YN DESC

