/* updateCancleSchdlRsvtDtl - kim.seong.ok */


UPDATE SBD310 SET

    RSVT_STTS_SE_CD   = #{RSVT_STTS_SE_CD},     /* 자원분류관리대분류구분코드           */
    LAST_MDFR_ID                = #{LAST_MDFR_ID},                  /* 최종수정자아이디        */
    LAST_MDFCN_DT               = SYSDATE                           /* 최종수정일시           */

WHERE 1=1
  AND INST_NO = #{INST_NO}
  AND USER_ID = #{USER_ID}
  AND RSVT_SN = #{RSVT_SN}
  AND UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}

